    "Shapes_AddLine_X2": "\u200F\u200F\u0627\u0644\u0627\u062D\u062F\u0627\u062B\u0649 x \u0627\u0644\u062E\u0627\u0635 \u0628\u0627\u0644\u0646\u0642\u0637\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629.",
    "Shapes_AddLine_Y2": "\u200F\u200F\u0627\u0644\u0627\u062D\u062F\u0627\u062B\u0649 y \u0627\u0644\u062E\u0627\u0635 \u0628\u0627\u0644\u0646\u0642\u0637\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629.",
