    "Math_Power_Exponent": "\uAC70\uB4ED\uC81C\uACF1 \uC5F0\uC0B0\uC5D0 \uC0AC\uC6A9\uB420 \uBC11\uC218",
    "Math_SquareRoot": "\uC8FC\uC5B4\uC9C4 \uC218\uC758 \uC81C\uACF1\uADFC\uC744 \uAD6C\uD569\uB2C8\uB2E4.",
    "Math_SquareRoot_Number": "\uC81C\uACF1\uADFC\uC774 \uD544\uC694\uD55C \uC218",
    "Program": "Program \uAC1C\uCCB4\uB294 \uD504\uB85C\uADF8\uB7A8 \uC791\uB3D9\uC5D0 \uB300\uD55C \uB3C4\uC6C0\uC744 \uC81C\uACF5\uD569\uB2C8\uB2E4.",
    "Program_End": "\uD504\uB85C\uADF8\uB7A8\uC744 \uB05D\uB0C5\uB2C8\uB2E4.",
    "Shapes": "Shape \uAC1C\uCCB4\uB294 \uADF8\uB798\uD53D \uCC3D\uC5D0 \uBAA8\uC591\uC744 \uCD94\uAC00, \uC774\uB3D9, \uD639\uC740 \uD68C\uC804 \uD558\uB294\uAC83\uC744 \uAC00\uB2A5\uD558\uAC8C \uD569\uB2C8\uB2E4.",
    "Shapes_AddRectangle": "\uC9C0\uC815\uD55C \uB108\uBE44\uC640 \uB192\uC774\uC758 \uC0BC\uAC01\uD615\uC744 \uCD94\uAC00 \uD569\uB2C8\uB2E4.",
    "Shapes_AddRectangle_Width": "\uC0AC\uAC01\uD615 \uBAA8\uC591\uC758 \uB108\uBE44",
    "Shapes_AddRectangle_Height": "\uC0AC\uAC01\uD615 \uBAA8\uC591\uC758 \uB192\uC774",
    "Shapes_AddEllipse": "\uC9C0\uC815\uD55C \uB108\uBE44\uC640 \uB192\uC774\uC758 \uD0C0\uC6D0\uD615\uC744 \uCD94\uAC00 \uD569\uB2C8\uB2E4.",
    "Shapes_AddEllipse_Width": "\uD0C0\uC6D0\uD615 \uBAA8\uC591\uC758 \uB108\uBE44",
    "Shapes_AddEllipse_Height": "\uD0C0\uC6D0\uD615 \uBAA8\uC591\uC758 \uB192\uC774",
    "Shapes_AddTriangle": "\uC9C0\uC815\uD55C \uC810\uB4E4\uB85C \uC774\uB8E8\uC5B4\uC9C4 \uC0BC\uAC01\uD615 \uBAA8\uC591\uC744 \uCD94\uAC00\uD569\uB2C8\uB2E4.",
    "Shapes_AddTriangle_X1": "\uCCAB\uBC88\uC9F8 \uC810\uC758 x \uC88C\uD45C",
    "Shapes_AddTriangle_Y1": "\uCCAB\uBC88\uC9F8 \uC810\uC758 y \uC88C\uD45C",
