    "GraphicsWindow_DrawEllipse_Height": "\uD0C0\uC6D0\uD615\uC758 \uB192\uC774",
    "GraphicsWindow_FillEllipse": "\uADF8\uB798\uD53D \uCC3D\uC758 \uC9C0\uC815\uD55C \uC704\uCE58\uC5D0 \uC0C9\uC774 \uCC44\uC6CC\uC9C4 \uD0C0\uC6D0\uD615\uC744 \uADF8\uB9BD\uB2C8\uB2E4.",
    "GraphicsWindow_FillEllipse_X": "\uD0C0\uC6D0\uD615\uC758 x \uC88C\uD45C",
    "GraphicsWindow_FillEllipse_Y": "\uD0C0\uC6D0\uD615\uC758 y \uC88C\uD45C",
